<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,Registry,MembershipApplications,Finance,DocumentCatalog};
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','Familientest'),('b','Anderer Verein');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('s','a','members',1);INSERT INTO actor_capabilities VALUES('s','local_finance')");
$n=0;function ok(bool $v,string $label):void{global $n;if(!$v)throw new RuntimeException($label);++$n;echo "PASS $label\n";}
function denied(callable $f,string $label):void{try{$f();}catch(DomainException){ok(true,$label);return;}throw new RuntimeException($label);}
$i=new MembershipApplications($db,'a','s');$r=new Registry($db,'s');$f=new Finance($db,'s');$cfg=$i->settings()['config'];$cfg['enabled']=true;$i->saveSettings($cfg,0);
$submit=fn($a)=>$i->submit($a,bin2hex(random_bytes(16)),1,true);
$base=['first_name'=>'Elternteil','last_name'=>'Familientest','email'=>'familie@example.invalid','birthday'=>'1990-01-02','address'=>'Testweg 1','membership_type'=>'family','family_members'=>'Kind, geboren 2018; weitere Person folgt'];
$parentApp=$submit($base);
$accept=fn($id,$target)=>$i->review($id,1,'accepted','Beschluss im Test dokumentiert',start:'2026-09-05',externalDecision:true,decisionDate:'2026-09-05',familyTarget:$target);
denied(fn()=>$accept($parentApp,''),'missing assignment blocks acceptance');
ok((int)$db->query('SELECT count(*) FROM contacts')->fetchColumn()===0,'missing assignment rolls back profile and numbering');
denied(fn()=>$accept($parentApp,'single'),'family application cannot silently become single contribution');
denied(fn()=>$i->review($parentApp,1,'accepted','Kein Beschluss',start:'2026-09-05',familyTarget:'new'),'acceptance needs online result or documented prior board decision');
$parent=$accept($parentApp,'new');$family=$r->family($parent);
ok($family['payer_contact_id']===$parent,'new family has explicit payer');
ok((int)$db->query('SELECT count(*) FROM finance_entries')->fetchColumn()===1,'acceptance creates one yearly family contribution');
$entry=$f->createAnnualContribution($parent,2026,$family['id']);
$childApp=$submit(array_replace($base,['first_name'=>'Kind','birthday'=>'2018-04-02','family_members'=>'Ergänzung zur bereits aufgenommenen Familie']));
$original=DocumentCatalog::query($db,"SELECT f.sha256 FROM document_files f JOIN document_links l ON l.club_id=f.club_id AND l.document_id=f.document_id WHERE l.source_type='application' AND l.source_id=?",[$childApp])->fetchColumn();
$familyChoice=$family['id'].':'.$family['version'];
denied(fn()=>$accept($childApp,$family['id'].':999'),'stale family selection rejected');
denied(fn()=>$accept($childApp,str_repeat('f',32).':1'),'unknown family rejected');
$child=$accept($childApp,$familyChoice);
ok($r->family($child)['id']===$family['id']&&$r->family($child)['payer_contact_id']===$parent,'later child joins existing family with unchanged payer');
ok($r->contact($child)['birthday']==='2018-04-02'&&$child!==$parent,'child has separate profile and birthday');
ok($r->contact($child)['email']===$r->contact($parent)['email'],'parent and child may share family email');
ok((int)$db->query('SELECT count(DISTINCT member_number) FROM memberships')->fetchColumn()===2,'each family person has separate member number');
ok((int)$db->query('SELECT count(*) FROM finance_entries')->fetchColumn()===1,'later admission creates no additional invoice');
ok($f->createAnnualContribution($child,2026,$family['id'])===$entry,'existing yearly family charge covers later child');
ok($f->entry($entry)['amount_cents']===7200&&(int)$db->query('SELECT count(*) FROM member_dues_people')->fetchColumn()===2,'one 72 EUR charge covers both people');
ok(json_decode($i->application($childApp)['answers'],true)['family_members']==='Ergänzung zur bereits aufgenommenen Familie','free text preserved');
$after=DocumentCatalog::query($db,"SELECT f.sha256 FROM document_files f JOIN document_links l ON l.club_id=f.club_id AND l.document_id=f.document_id WHERE l.source_type='application' AND l.source_id=?",[$childApp])->fetchColumn();
ok($original===$after,'family linking leaves original application PDF unchanged');
$duplicate=$submit(array_replace($base,['first_name'=>'Kind']));$now=$r->family($parent);
denied(fn()=>$accept($duplicate,$now['id'].':'.$now['version']),'shared email never bypasses same-person duplicate check');
echo "$n family admission checks passed\n";
